import os
from PIL import Image

def import_image(file_path):
    try:
        image = Image.open(file_path)
        image.save("temp.jpg")
        os.system("convert temp.jpg output.jpg")
        print("Image imported successfully.")
    except Exception as e:
        print(f"Error: {e}")
